"""Unit stats in the map hover box (MT / HIT / AS / AVO), the same patch the PC port uses.

Generated by the port's tools/fe4hover.py. The new code lives at $85:FA00; the word at FLAG
switches it on (1) or off (0). Headerless file offsets.
"""
FLAG = 0x05FA00
PATCHES = [
    (0x05C673, bytes.fromhex('a90900'), bytes.fromhex('204afb')),
    (0x05C679, bytes.fromhex('a90500'), bytes.fromhex('2058fb')),
    (0x05C7B4, bytes.fromhex('a9bfc7'), bytes.fromhex('2066fb')),
    (0x05C81D, bytes.fromhex('c9d000'), bytes.fromhex('2074fb')),
    (0x05C822, bytes.fromhex('c93000'), bytes.fromhex('2085fb')),
    (0x05C827, bytes.fromhex('a92800'), bytes.fromhex('2096fb')),
    (0x05C82C, bytes.fromhex('a9c000'), bytes.fromhex('20a4fb')),
    (0x05C833, bytes.fromhex('e90300'), bytes.fromhex('20b2fb')),
    (0x05C83C, bytes.fromhex('c93000'), bytes.fromhex('20c3fb')),
    (0x05C842, bytes.fromhex('694800'), bytes.fromhex('20d4fb')),
    (0x05C849, bytes.fromhex('e90600'), bytes.fromhex('20e5fb')),
    (0x05C9E8, bytes.fromhex('b90bca'), bytes.fromhex('20f6fb')),
    (0x05C9F0, bytes.fromhex('b90dca'), bytes.fromhex('2004fc')),
    (0x05C9F9, bytes.fromhex('b92bca'), bytes.fromhex('2012fc')),
    (0x05CA01, bytes.fromhex('b92dca'), bytes.fromhex('2020fc')),
    (0x05C7AE, bytes.fromhex('2019c8'), bytes.fromhex('2036fb')),
    (0x05C97E, bytes.fromhex('209fc9'), bytes.fromhex('2020fb')),
    (0x05FA00, bytes.fromhex(''), bytes.fromhex('')),
]


def apply(rom, on=True):
    """Add the patch to a headerless ROM (bytearray). False if the game's code differs there."""
    def same(off, data, skip=0):
        return bytes(rom[off + skip:off + len(data)]) == data[skip:]
    if not all(same(off, new, 2 if len(new) > 16 else 0) for off, orig, new in PATCHES):
        if not all(same(off, orig) for off, orig, new in PATCHES):
            return False
        for off, orig, new in PATCHES:
            rom[off:off + len(new)] = new
    rom[FLAG] = 1 if on else 0
    rom[FLAG + 1] = 0
    return True
